     8	public class Datos
     9	{
    10	    public IReadOnlyList<Usuario> Estudiantes { get; }
    11	    public IReadOnlyList<Usuario> Coordinadores { get; }
    12	    public IReadOnlyList<JsonElement> Notas { get; }
    13	    public IReadOnlyList<JsonElement> Asistencia { get; }
    14	
    15	    public Datos(string carpeta)
    16	    {
    17	        var est = new List<Usuario>();
    18	        var coo = new List<Usuario>();
    19	        var notas = new List<JsonElement>();
    20	        var asis = new List<JsonElement>();
    21	        if (Directory.Exists(carpeta))
    22	        {
    23	            foreach (var archivo in Directory.GetFiles(carpeta, "*.json").OrderBy(f => f, StringComparer.Ordinal))
    24	            {
    25	                using var doc = JsonDocument.Parse(File.ReadAllText(archivo));
    26	                if (doc.RootElement.ValueKind != JsonValueKind.Array) continue;
    27	                foreach (var e in doc.RootElement.EnumerateArray())
    28	                {
    29	                    if (e.ValueKind != JsonValueKind.Object) continue;
    30	                    var c = e.Clone();
    31	                    if (Tiene(c, "estudianteId") && Tiene(c, "definitiva")) notas.Add(c);
    32	                    else if (Tiene(c, "estudianteId") && Tiene(c, "inasistencias")) asis.Add(c);
    33	                    else if (Tiene(c, "id") && Tiene(c, "programa"))
    34	                    {
    35	                        var esEstudiante = Tiene(c, "semestre");
    36	                        var u = new Usuario(esEstudiante ? "estudiante" : "coordinador",
    37	                            Texto(c, "id"), Texto(c, "nombre"), Texto(c, "programa"));
    38	                        (esEstudiante ? est : coo).Add(u);
    39	                    }
    40	                }
    41	            }
    42	        }
    43	        Estudiantes = est;
    44	        Coordinadores = coo;
    45	        Notas = notas;
    46	        Asistencia = asis;
    47	    }
    48	
    49	    static bool Tiene(JsonElement e, string p) => e.TryGetProperty(p, out _);
    50	    static string Texto(JsonElement e, string p) => e.TryGetProperty(p, out var v) ? v.GetString() ?? "" : "";
    51	
    52	    public Usuario? BuscarUsuario(string rol, string id) =>
    53	        (rol == "estudiante" ? Estudiantes : rol == "coordinador" ? Coordinadores : [])
    54	            .FirstOrDefault(u => u.Id == id);
